<?= $this->extend('shop/layout') ?>
<?= $this->section('content') ?>
<div class="card p-4"><h1><?= esc($product['name']) ?></h1><?php if ($product['image']): ?><img class="product-image" src="<?= site_url('products/'.$product['id'].'/image') ?>" alt="<?= esc($product['name']) ?>"><?php endif ?><p class="mt-3"><?= nl2br(esc($product['description'])) ?></p><p>Rp <?= esc($product['price']) ?> ? Stok <?= esc($product['stock']) ?></p><?php if (!$user): ?><a href="<?= site_url('login') ?>">Login untuk menambah keranjang</a><?php elseif ($user['role']==='customer' && $product['stock']>0): ?><form action="<?= site_url('cart/'.$product['id']) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="mode" value="add"><label for="quantity">Kuantitas</label><input class="form-control mb-3" style="max-width:150px" type="number" id="quantity" name="quantity" value="1" min="1" max="<?= esc($product['stock']) ?>" required><button class="btn btn-primary">Tambah keranjang</button></form><?php else: ?><p>Produk tidak tersedia untuk pembelian akun ini.</p><?php endif ?></div>
